import java.util.*;
import java.io.*;

public class Main {
    static int[] areConnected(int n, int threshold, int[][] queries) {
        // Write your solution here
        return new int[queries.length];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int threshold = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            in.nextToken(); queries[i][0] = (int) in.nval;
            in.nextToken(); queries[i][1] = (int) in.nval;
        }
        int[] res = areConnected(n, threshold, queries);
        StringBuilder sb = new StringBuilder();
        for (int r : res) sb.append(r).append('\n');
        System.out.print(sb);
    }
}
